   188	uint8_t Address::GetScope(void) const
   189	{
   190	    uint8_t rval;
   191	
   192	    if (IsMulticast())
   193	    {
   194	        rval = mFields.m8[1] & 0xf;
   195	    }
   196	    else if (IsLinkLocal())
   197	    {
   198	        rval = kLinkLocalScope;
   199	    }
   200	    else if (IsLoopback())
   201	    {
   202	        rval = kNodeLocalScope;
   203	    }
   204	    else
   205	    {
   206	        rval = kGlobalScope;
   207	    }
   208	
   209	    return rval;
   210	}
